// Golden vectors below were generated by an independent python3
// reimplementation of the same 9-step formula (see task-2-brief.md and
// PayrollCalculator.hpp's file header for the order of calculation and its
// sources). Rates/constants match the Task 1 seed in
// migrations/011_tax_reference.sql (2026 values).
#include <gtest/gtest.h>

#include "payroll/PayrollCalculator.hpp"

namespace {

Payroll::Rates make_rates() {
    Payroll::Rates r;
    r.ipn_bp = 1000;
    r.opv_bp = 1000;
    r.opvr_bp = 350;
    r.so_bp = 500;
    r.osms_bp = 300;
    r.vosms_bp = 200;
    r.social_tax_bp = 600;
    r.mrp_tiyn = 432500;
    r.mzp_tiyn = 8500000;
    r.ipn_deduction_mrp = 30;
    r.opv_base_max_mzp = 50;
    r.so_base_min_mzp = 1;
    r.so_base_max_mzp = 7;
    r.vosms_base_max_mzp = 20;
    r.osms_base_max_mzp = 40;
    r.social_tax_applies = true;
    return r;
}

}  // namespace

TEST(PayrollCalculator, ApplyBpRoundsHalfUp) {
    EXPECT_EQ(Payroll::apply_bp(333, 1000), 33);
    EXPECT_EQ(Payroll::apply_bp(335, 1000), 34);
}

// (a) 85 000 tg (= 1 MZP) with IPN deduction claimed.
TEST(PayrollCalculator, GoldenCaseA_OneMzpWithDeduction) {
    const auto rates = make_rates();
    Payroll::Input in;
    in.gross_tiyn = 8500000;
    in.ipn_deduction_claimed = true;
    in.opvr_exempt = false;

    const auto out = Payroll::calculate(in, rates);

    EXPECT_EQ(out.opv, 850000);
    EXPECT_EQ(out.vosms, 170000);
    EXPECT_EQ(out.ipn, 0);
    EXPECT_EQ(out.net, 7480000);
    EXPECT_EQ(out.opvr, 297500);
    EXPECT_EQ(out.so, 425000);
    EXPECT_EQ(out.osms, 255000);
    EXPECT_EQ(out.social_tax, 448800);
    EXPECT_EQ(out.employer_cost_total, 9926300);
}

