// НК РК ст.363 defines a progressive ИПН scale (10% up to 8500 МРП/year
// cumulative income, 15% above — on 2026 constants that's ~3.06M tg/month).
// P2's calculate() deliberately stays single-rate: it has no year-to-date
// income context to compute the cumulative threshold against. This test
// pins that documented gap for a salary well past the annual threshold —
// when year-to-date tracking is added, this test (and Rates::ipn_bp's flat
// application at Step 3) must be intentionally rewritten, not silently
// left passing on the old single-rate assumption.
TEST(PayrollCalculator, HighSalaryStillUsesFlatRateInP2) {
    const auto rates = make_rates();
    Payroll::Input in;
    in.gross_tiyn = 500000000;  // 5 000 000 tg/month, far above the 8500 MRP/year threshold
    in.ipn_deduction_claimed = true;
    in.opvr_exempt = false;

    const auto out = Payroll::calculate(in, rates);

    EXPECT_EQ(out.opv, 42500000);
    EXPECT_EQ(out.vosms, 3400000);
    // Flat 10% throughout ipn_base, NOT the 15% marginal rate the real
    // progressive scale would apply above the annual threshold.
    EXPECT_EQ(out.ipn, 44112500);
    EXPECT_EQ(out.net, 409987500);
    EXPECT_EQ(out.opvr, 14875000);
    EXPECT_EQ(out.so, 2975000);
    EXPECT_EQ(out.osms, 10200000);
    EXPECT_EQ(out.social_tax, 27246000);
    EXPECT_EQ(out.employer_cost_total, 555296000);
}

TEST(PayrollCalculator, SocialTaxSkippedOnSnr) {
    auto rates = make_rates();
    rates.social_tax_applies = false;
    Payroll::Input in;
    in.gross_tiyn = 30000000;

    const auto out = Payroll::calculate(in, rates);

    EXPECT_EQ(out.social_tax, 0);
    // employer_cost_total should not include the skipped social tax.
    EXPECT_EQ(out.employer_cost_total, in.gross_tiyn + out.opvr + out.so + out.osms);
}

